import numpy as np

def calculate_distance(point1, point2):
    return np.linalg.norm(point1 - point2)

def find_farthest_points(N, points):
    result = []
    for i in range(N):
        far_d, far_id = -1, -1
        for j in range(N):
            if i == j: continue
            d = calculate_distance(points[i], points[j])
            if d > far_d:
                far_d, far_id = d, j + 1
        result.append(far_id)
    return result

